// This style of import is necessary for storybook to automatically generate the documentation for prop types
import * as React from "react";
import "./TextAreaField.scss";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon } from "../../assets/icons";


export interface TextAreaFieldProps {
  /**
   * Identifying value for the text area field.
   */
  id: string;

  /**
  * Number of visible character rows.
  */
  rows?: number;
  /**
  * Determines the colour of textarea (primary, secondary, tertiary).
  */
  colour?: "primary" | "secondary" | "tertiary"; 
  
  /**
   * Label to be displayed above the text area field.
   */
  label: string;
  /**
   * Text to be displayed when the field is empty.
   */
  placeholder?: string;
  /**
   * Value to be displayed inside the textarea field.
   */
  value?: string;
  /**
   * Sets the maximum number of characters that can be entered before an error is displayed.
   */
  maxCharacters?: number;
  /**
   * Optional text to be displayed below the entry field.
   */
  supportingText?: string;
  /**
   * Text to be displayed when number of characters is exceeded.
   */
  errorText?: string;
   /**
   * Text to be displayed in a help tooltip next to the label.
   */
   tooltipText?: string;
   /**
   * The placement of the overlay in relation to the icon.
   */
  tooltipPlacement?: "right" | "left" | "top" | "bottom";
   /**
    * React SVG icon object to be displayed in a help tooltip next to the label.
    */
   tooltipIcon?: keyof typeof SvgMpaIcon | string;
  /**
   * Controls if the field is disabled.
   */
  disabled?: boolean;
  /**
   * Boolean which determines if the field must have a value.
   */
  required?: boolean;
  /**
   * Custom onChange function that can be used to customize behavior.
   */
  onChange?: (event: React.ChangeEvent<HTMLTextAreaElement>) => void;
  /**
   * Custom className that can be passed to the element for overriding styling.
   */
  className?: string;

}

export const TextAreaField: React.FC<TextAreaFieldProps> = ({
  id,
  rows=4,
  label,
  value,
  maxCharacters,
  supportingText,
  errorText="",
  disabled,
  required=false,
  placeholder,
  tooltipText,
  tooltipPlacement="top",
  tooltipIcon,
  onChange,
  colour, 
}) => {
  const [text, setText] = React.useState(value ? value : "");

  React.useEffect(() => {
    if (value !== text) {
      setText(value ? value.slice(0, maxCharacters ?? value.length) : "");
    }
  }, [value, maxCharacters]);

  
  const handleChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    const inputValue = event.target.value;
    const truncatedValue = inputValue.slice(0, maxCharacters);
    setText(truncatedValue);
    if (onChange) {
      onChange(event);
    }
  };
  const characterCount = text.length;

  const renderTooltip = () => {
  if (label && tooltipText && tooltipText.trim().length > 0 && tooltipIcon) {
    return (
      
        <span className="label-tooltip-icon">
          <MpaIcon
            colour="var(--mpa-gray)"
            iconName={tooltipIcon}
            tooltipText={tooltipText}
            tooltipPlacement={tooltipPlacement}
          />
        </span>
      
    );
  }
  return null;
};


  return (
    <div className={`text-area-field`}>
      {label && 
      <label htmlFor={id} className="form-label mpa-label">
        {label} { tooltipText && renderTooltip()} 
      </label>}
      {required ?(<span className={'label-required'}>*</span>
        ):(<span className={'label-optional'}>(Optional)</span>)}
      <textarea
        id={id}
        rows={rows}
        value={text}
        onChange={handleChange}
        disabled={disabled}
        className={`text-area-form ${colour} ${errorText ? "error" : ""} ${disabled ? "disabled" : ""}`}
        maxLength={maxCharacters}
        placeholder={placeholder}
      />
      {errorText?.trim() !== ""   && (
        <div>         
            <p className="error-text"><MpaIcon iconName="AlertCircle" colour="var(--mpa-red-80)"/>
            <span className="error-text-padding">
            {errorText}
            </span>
            </p>
        </div>
      )}

      <div className="area-field-supporting-text-container">
        {supportingText && (
          <div className="supporting-text-wrapper">
            <span className="supporting-text">{supportingText}</span>
          </div>
        )}
        
        {maxCharacters && (
          <div className="area-field-character-count-wrapper">
            <span className="character-count">
              {characterCount}/{maxCharacters}
            </span>
          </div>
        )}
      </div>
    </div>
  );
};

export default TextAreaField;